    async fn embed(&self, text: &str, input_type: &str) -> Result<Vec<f32>> {
        #[derive(Serialize)]
        struct Req<'a> {
            input: Vec<&'a str>,
            model: &'a str,
            input_type: &'a str,
            truncation: bool,
            output_dimension: u64,
        }
        #[derive(Deserialize)]
        struct Resp {
            data: Vec<EmbData>,
        }
        #[derive(Deserialize)]
        struct EmbData {
            embedding: Vec<f32>,
        }

        let url = voyage_url_for_key(&self.voyage_key);

        let resp: Resp = self
            .http
            .post(url)
            .bearer_auth(&self.voyage_key)
            .json(&Req {
                input: vec![text],
                model: &self.voyage_model,
                input_type,
                truncation: true,
                output_dimension: VECTOR_DIM,
            })
            .send()
            .await?
            .error_for_status()?
            .json()
            .await?;

        resp.data
            .into_iter()
            .next()
            .map(|d| d.embedding)
            .context("Voyage returned no embeddings")
    }
